    bool active : 1;
    bool hasGravity : 1;
    bool hasDrag : 1;

    Particle() : active(false), hasGravity(false), hasDrag(false) {}

    // 获取生命周期进度 [0, 1]
    float getLifeProgress() const { 
        return 1.0f - (life / maxLife); 
    }

    bool isAlive() const { 
